evision_group_public_id":"f345184b-e27d-4319-8078-2a45c05b3d07","availability_flags_explicit":true},{"id":68,"pool":"EXAM","title":"DOC22 FILL_IN_THE_BLANKS_DRAG_AND_DROP 36e7d5bb7a0076c4 | Open Door Policy","status":"APPROVED","deleted":false,"version":1,"public_id":"ee6ffbae-0f9e-4340-af04-c21b742ccd55","tenant_id":null,"created_at":"2026-10-28T16:07:27.075125+00:00","is_current":true,"updated_at":"2026-10-28T16:07:27.085019+00:00","visibility":"SHARED","prompt_text":"An \"Open Door\" policy ensures equal commercial and industrial rights for the nationals of all countries within a certain territory. As a {{1}} policy, it was first advanced by the United States, but it was {{2}} in the typical most-favored-nation clause of the treaties concluded with China after the Opium War (1839-42). Although the Open Door is generally {{3}} with China, it also received recognition at the Berlin Conference of 1885, which declared that no power could {{4}} preferential duties in the Congo basin.","pte_task_type":"FILL_IN_THE_BLANKS_DRAG_AND_DROP","task_type_key":"FILL_IN_THE_BLANKS_DRAG_AND_DROP","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":null,"image_prompt_ref":null,"rejection_reason":null,"task_type_section":"READING","available_for_exam":true,"correct_answer_text":"1.specific, 2.rooted, 3.associated, 4.levy","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"c859a088-2968-4e09-a237-c4b361c61276","availability_flags_explicit":true},{"id":69,"pool":"EXAM","title":"DOC22 FILL_IN_THE_BLANKS_DRAG_AND_DROP faab7d97527b61b0 | Papal Reform","status":"APPROVED","deleted":false,"version":1,"public_id":"590654e4-c897-44f3-a6dc-b6c64b4ac70d","tenant_id":null,"created_at":"2026-10-28T16:07:27.097402+00:00","is_current":true,"updated_at":"2026-10-28T16:07:27.108294+00:00","visibility":"SHARED","prompt_text":"Since the last papal reform, several {{1}} have been offered to make the Western calendar more useful or {{2}} . Very few reforms, such as the rather different decimal French Republican and Soviet calendars, had gained official {{3}} but each was put out of use shortly after its introduction.","pte_task_type":"FILL_IN_THE_BLANKS_DRAG_AND_DROP","task_type_key":"FILL_IN_THE_BLANKS_DRAG_AND_DROP","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":null,"image_prompt_ref":null,"rejection_reason":null,"task_type_section":"READING","available_for_exam":true,"correct_answer_text":"1.proposals, 2.regular, 3.acceptance","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"25c3054c-b833-46d8-9971-1cae9409b4fa","availability_flags_explicit":true},{"id":70,"pool":"EXAM","title":"DOC22 FILL_IN_THE_BLANKS_DRAG_AND_DROP 3d4c18732a3d82fb | Dark Matter","status":"APPROVED","deleted":false,"version":1,"public_id":"07c70037-61d4-4a4a-96ea-f6d055a7883d","tenant_id":null,"created_at":"2026-10-28T16:07:27.120059+00:00","is_current":true,"updated_at":"2026-10-28T16:07:27.131795+00:00","visibility":"SHARED","prompt_text":"A new interdisciplinary centre for the study of the frontiers of the universe, from the tiniest subatomic particle to the largest chain of galaxies, has been formed at the University of Texas at Austin. The Texas Cosmology Center will be a way for the university's departments of Astronomy and Physics to {{1}} on research that concerns them both. \"This centre will bring the two departments together in an area where they {{2}} —— in the physics of the very early universe,\" said Dr. Neal Evans, Astronomy Department chair. Astronomical observations have revealed the presence of dark matter and dark energy, {{3}} that challenge our knowledge of fundamental physics. And today's leading theories in physics {{4}} energies so high that no earthbound particle accelerator can test them. They need the universe as their {{5}} . Dr. Steven Weinberg, Nobel laureate and professor of physics at the university, called the advent of the centre \"a very exciting development\" for that department.","pte_task_type":"FILL_IN_THE_BLANKS_DRAG_AND_DROP","task_type_key":"FILL_IN_THE_BLANKS_DRAG_AND_DROP","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":null,"image_prompt_ref":null,"rejection_reason":null,"task_type_section":"READING","available_for_exam":true,"correct_answer_text":"1.collaborate, 2.overlap, 3.discoveries, 4.involve, 5.laboratory","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"abb610e4-06c7-4e96-bfd7-491a2754b2f9","availability_flags_explicit":true},{"id":71,"pool":"EXAM","title":"DOC22 FILL_IN_THE_BLANKS_DRAG_AND_DROP 375ea9613fcb34f0 | Thea Proctor","status":"APPROVED","deleted":false,"version":1,"public_id":"8b911c38-dd0a-4843-90aa-8f8107d8a792","tenant_id":null,"created_at":"2026-10-28T16:07:27.144541+00:00","is_current":true,"updated_at":"2026-10-28T16:07:27.15543+00:00","visibility":"SHARED","prompt_text":"Thea Proctor was just sixteen when her entry at the Bowral Art Competition caught the eye of the judge, Arthur Streeton. It was the first of many associations with art world {{1}} . The next year saw her at the Julian Ashton Art School in the illustrious company of Elioth Gruner, Sydney Long and George Lambert, for whom she often posed and who {{2}} her great friend until his death in 1930. Lambert's paintings and sketches of Proctor emphasize the elegance of her dress. A keen interest in fashion was just one {{3}} of her fascination with design, and she saw herself as an early style guru on a quest to rid Australian art of \"its lack of imagination and inventive design\". Skilled in watercolor and drawing, Proctor did not {{4}} herself to paper, canvases or to her popular magazine illustrations; she designed theater sets and a restaurant interior and wrote on a range of subjects from flower arranging to the colors of cars. It made for a busy and {{5}} life but, as she said, she was not the sort of person \"who could sit at home and knit socks.\"","pte_task_type":"FILL_IN_THE_BLANKS_DRAG_AND_DROP","task_type_key":"FILL_IN_THE_BLANKS_DRAG_AND_DROP","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":null,"image_prompt_ref":null,"rejection_reason":null,"task_type_section":"READING","available_for_exam":true,"correct_answer_text":"1.recruits, 2.remained, 3.aspect, 4.limit, 5.varied","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"6f126347-1837-4f8c-95a0-2caf87f91061","availability_flags_explicit":true},{"id":72,"pool":"EXAM","title":"DOC22 SUMMARIZE_SPOKEN_TEXT 45f0799335e52df6 | Technological Nature","status":"APPROVED","deleted":false,"version":1,"public_id":"81e2ca28-da81-4536-a016-979f0d3e1788","tenant_id":null,"created_at":"2026-10-28T16:07:28.115664+00:00","is_current":true,"updated_at":"2026-10-28T16:07:28.125994+00:00","visibility":"SHARED","prompt_text":"Technological nature ... you may have heard this term... it's a term used to describe a picture of a natural scene that\"s been produced using computer graphics so that basically it isn't a real view - say of a garden or field - it's a virtual one - it's a picture that looks like a real scene, Now, looking at scenes of nature is known to have an effect on people's health and well-being. So for someone who's ill, for a patient in a hospital, does a virtual view of a garden have the same impact as a real one? Does it have the same beneficial effects when you look at it? Because that would be good. Well, um, if you test this out, if you put a group of people in a room with a real view and another group of people in a room with a virtual view - an unreal view - you can see what happens when they get stressed. If you give both groups a task that is slightly stressful and increases their heart rate and, um, what you'll find is that the people who have the real garden scene outside their window to look at - their heart rate goes back to normal more quickly than those of the people in the other group who only have a virtual view to look at. So, yes, there is a difference - people's recovery from stress is faster in the room with the real view.","pte_task_type":"SUMMARIZE_SPOKEN_TEXT","task_type_key":"SUMMARIZE_SPOKEN_TEXT","ever_published":true,"max_word_count":70,"min_word_count":50,"revision_number":1,"audio_prompt_ref":"1f2b3f07-62bb-48cb-871b-83a7cc1b1acf","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":null,"supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":"Technological nature refers to a computerized picture of a natural scene. To find out if this has the same beneficial effect as a real scene, we can put a group of people in a room with a real view and another group in a room with a virtual view. The group in the room with the real view will recover more quickly from stress than the other group.","available_for_practice":false,"revision_group_public_id":"bd291034-f611-487e-ad52-b202e966cc50","availability_flags_explicit":true},{"id":73,"pool":"EXAM","title":"DOC22 MC_LISTENING_MULTIPLE de4bd9ff9d36cea8 | Heyday","status":"APPROVED","deleted":false,"version":1,"public_id":"345725f0-8e44-4c36-9442-11eefab41757","tenant_id":null,"created_at":"2026-10-28T16:07:29.059678+00:00","is_current":true,"updated_at":"2026-10-28T16:07:29.070055+00:00","visibility":"SHARED","prompt_text":"The heyday of the English landscape garden was the 18th century, and it stood for many things: the appreciation of natural beauty, of course, but also the idea of a civilized life, good taste, one's personal philosophy, and one's social status. Gardens also - though it is hard for us to credit - became expressions of their owners' political affiliations. Until the picturesque style emerged as part and parcel of the Romantic Movement, gardens had been strictly formal, laid out with mathematical precision following the Italian and French examples. There then came a backlash against this rigid formality, led by, among others, the poet Alexander Pope. Pope and his allies argued for a more natural nature.\nLord Burlington was a major figure in the landscape garden movement, and he was famously influenced by his love of the Italian architect, Andrea Palladia, along with the picturesque or romanticized landscapes of Italian classical painting. With these in mind, he scattered his gardens and parks with classical Greek and Roman temples and statues. In other words, he wanted to make the garden look like those paintings.\n\nWhich of the following are mentioned as influences on the English landscape garden?","pte_task_type":"MC_LISTENING_MULTIPLE","task_type_key":"MC_LISTENING_MULTIPLE","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"6e83b12d-7a40-4c7c-ab12-a5d246868123","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"The Romantic Movement\nItalian classical painting","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"f4f12b86-1eac-404a-bdf8-122d002ddf4f","availability_flags_explicit":true},{"id":74,"pool":"EXAM","title":"DOC22 MC_LISTENING_MULTIPLE a231483c0014e8db | MCM-L","status":"APPROVED","deleted":false,"version":1,"public_id":"26c136be-aac4-4add-9779-fe6a9f720039","tenant_id":null,"created_at":"2026-10-28T16:07:30.178145+00:00","is_current":true,"updated_at":"2026-10-28T16:07:30.190013+00:00","visibility":"SHARED","prompt_text":"Today we are going to talk some more about architecture and what makes for a good design. There are of course a whole range of qualities that most architects would like their buildings to possess. One of these is the durability of the building. Architects must consider how well the building will stand up to the ravages of climate and time. Will it remain robust and in good condition? Clearly, requirements will vary according to the surroundings of the building in question. A design that is suitable for Dubai will have different needs from one for Moscow. Then of course it's essential to consider the appearance of the building.\nRegardless of what its purpose may be, will people find pleasure in looking at it! An original and still respected writer on architecture, the Roman Vitrtlvius, wrote in the first century that a building should delight people and should raise their spirits. Again. tastes may vary from one society to the next, but the prinCiple remains the same.\n\nWhich of these qualities of a building does the speaker mention as being","pte_task_type":"MC_LISTENING_MULTIPLE","task_type_key":"MC_LISTENING_MULTIPLE","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"4ef682be-990a-4203-a9df-54d21a030b72","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"how attractive the building is to look at\nhow long the building is likely to last","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"73fac17c-d630-4157-b0a9-79fa125d883c","availability_flags_explicit":true},{"id":75,"pool":"EXAM","title":"DOC22 MC_LISTENING_MULTIPLE e7458fc9b4c141e0 | Social Contract","status":"APPROVED","deleted":false,"version":1,"public_id":"aef2c4c1-c0ea-43eb-a076-7f3f8bbe15ae","tenant_id":null,"created_at":"2026-10-28T16:07:31.344422+00:00","is_current":true,"updated_at":"2026-10-28T16:07:31.355515+00:00","visibility":"SHARED","prompt_text":"You may not know much, if anything, about Jean-Jacques Rousseau, but you have probably heard the well-known quote: \"Man is born free, and everywhere he is in chains.\" In his early work, Rousseau argued that mankind was happiest and at its best in a \"state of nature\" - that is, before the creation of society and civilization. He saw society as artificial and corrupt, and that good people were corrupted by it. The Social Contract is perhaps the most enduring and well-known of his books, covering pretty well every aspect of Man in society. However, in this book, his attitude to the condition of Man in a state of nature changes. In such conditions, man is brutish and competitive by nature, and there is no law or morality. Therefore, because it is easier to survive by joining forces with others, people form societies to better fight anything that might endanger their situation. Rousseau's political philosophy has had a profound influence on later thinkers, even though, or perhaps especially because, it is open to many interpretations. But political philosophy is not everybody's cup of tea. In his own time, Rousseau was a bestseller, with novels such as The New Heloise and, especially, Emile, though even the latter is not free of his constant desire to improve society. It illustrates his ideas about the best form of education, which involves educating a child's emotions before their reason. This too had a profound influence on educational theorists.\n\nWhich of the following statements is true of Rousseau's beliefs in The Social Contract?","pte_task_type":"MC_LISTENING_MULTIPLE","task_type_key":"MC_LISTENING_MULTIPLE","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"587f7a87-49c3-4fea-9a5b-1daabe390897","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"Men form societies to better cope with the dangers in life.\nBy forming societies, law and morality come into force.","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"1c0eb707-5bcc-4507-be3e-70b38d72954b","availability_flags_explicit":true},{"id":76,"pool":"EXAM","title":"DOC22 FILL_IN_THE_BLANKS_TYPE_IN a024c9ea1d24d952 | [MOCK] Barred Owls","status":"APPROVED","deleted":false,"version":1,"public_id":"02421e60-bee6-4a61-9d8e-ce80aa81f657","tenant_id":null,"created_at":"2026-10-28T16:07:32.283288+00:00","is_current":true,"updated_at":"2026-10-28T16:07:32.292443+00:00","visibility":"SHARED","prompt_text":"Barred owls are large, round-headed birds that were once found mainly in the {{0}} forests of North America. Over the last century, however, they have spread {{1}} and now compete with the smaller spotted owl for food and nesting sites. Researchers believe that changes in {{2}}, such as new trees growing on the open plains, allowed the birds to cross areas that had previously been a natural {{3}}. Wildlife managers are still debating how to {{4}} the native species without harming the newcomers.","pte_task_type":"FILL_IN_THE_BLANKS_TYPE_IN","task_type_key":"FILL_IN_THE_BLANKS_TYPE_IN","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"12d5ef23-ca32-4a88-a052-1c6de260f1d0","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"[\"eastern\",\"westward\",\"habitat\",\"barrier\",\"protect\"]","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":"Barred owls are large, round-headed birds that were once found mainly in the eastern forests of North America. Over the last century, however, they have spread westward and now compete with the smaller spotted owl for food and nesting sites. Researchers believe that changes in habitat, such as new trees growing on the open plains, allowed the birds to cross areas that had previously been a natural barrier. Wildlife managers are still debating how to protect the native species without harming the newcomers.","available_for_practice":false,"revision_group_public_id":"ec7b0c11-ff63-4e47-b8ae-fd211b573e9c","availability_flags_explicit":true},{"id":77,"pool":"EXAM","title":"DOC22 FILL_IN_THE_BLANKS_TYPE_IN 55f665d588bcf36f | [MOCK] Pearl Oysters","status":"APPROVED","deleted":false,"version":1,"public_id":"b1e1a77d-79e5-4d30-b8ef-e8380a322a83","tenant_id":null,"created_at":"2026-10-28T16:07:33.305488+00:00","is_current":true,"updated_at":"2026-10-28T16:07:33.318582+00:00","visibility":"SHARED","prompt_text":"Natural pearls form when a tiny {{0}}, such as a grain of sand or a parasite, becomes trapped inside an oyster's shell. To protect itself, the oyster covers the object with layer after layer of a smooth substance called {{1}}. Because this process can take several {{2}}, natural pearls have always been rare and extremely valuable. Today, most pearls on the market are {{3}}, which means that farmers insert a small bead into the oyster by hand and then return it to the water to {{4}}.","pte_task_type":"FILL_IN_THE_BLANKS_TYPE_IN","task_type_key":"FILL_IN_THE_BLANKS_TYPE_IN","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"ce29aff0-7299-4042-a6e1-6623ab13e4ea","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"[\"irritant\",\"nacre\",\"years\",\"cultured\",\"grow\"]","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":"Natural pearls form when a tiny irritant, such as a grain of sand or a parasite, becomes trapped inside an oyster's shell. To protect itself, the oyster covers the object with layer after layer of a smooth substance called nacre. Because this process can take several years, natural pearls have always been rare and extremely valuable. Today, most pearls on the market are cultured, which means that farmers insert a small bead into the oyster by hand and then return it to the water to grow.","available_for_practice":false,"revision_group_public_id":"58ed25b0-93cf-41bd-8970-273295224516","availability_flags_explicit":true},{"id":78,"pool":"EXAM","title":"DOC22 FILL_IN_THE_BLANKS_TYPE_IN d7ee66c4bdae50c3 | [MOCK] Primary Text","status":"APPROVED","deleted":false,"version":1,"public_id":"5c5f87b7-ce95-481b-b7bb-4f57e32aa97a","tenant_id":null,"created_at":"2026-10-28T16:07:34.234199+00:00","is_current":true,"updated_at":"2026-10-28T16:07:34.244364+00:00","visibility":"SHARED","prompt_text":"When students begin a research project, they are often told to rely on primary texts rather than secondary {{0}}. A primary text is an original document, such as a letter, a diary or a scientific report, written at the time of the events it {{1}}. Secondary texts, by contrast, {{2}} or comment on those original materials. Both types are useful, but reading the primary material first allows students to form their own {{3}} before they are influenced by the views of other {{4}}.","pte_task_type":"FILL_IN_THE_BLANKS_TYPE_IN","task_type_key":"FILL_IN_THE_BLANKS_TYPE_IN","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"cc90c124-e900-4cf4-9c7e-1db0e743ba04","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"[\"sources\",\"describes\",\"interpret\",\"opinions\",\"scholars\"]","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":"When students begin a research project, they are often told to rely on primary texts rather than secondary sources. A primary text is an original document, such as a letter, a diary or a scientific report, written at the time of the events it describes. Secondary texts, by contrast, interpret or comment on those original materials. Both types are useful, but reading the primary material first allows students to form their own opinions before they are influenced by the views of other scholars.","available_for_practice":false,"revision_group_public_id":"f77159b1-90d7-4236-b0da-e1a037bbcab4","availability_flags_explicit":true},{"id":79,"pool":"EXAM","title":"DOC22 HIGHLIGHT_CORRECT_SUMMARY 2f08a30fcfba3097 | Cliche","status":"APPROVED","deleted":false,"version":1,"public_id":"aae76d49-fa1b-41b7-a3c5-9acb3c660b2b","tenant_id":null,"created_at":"2026-10-28T16:07:35.327486+00:00","is_current":true,"updated_at":"2026-10-28T16:07:35.33731+00:00","visibility":"SHARED","prompt_text":"A cliche, as you know, is an overused and worn out phrase - and ... um ... these are to be avoided like the plague in your essays. Indeed, someone once said, I quote, \"there is no greater danger to either education or thinking than the popular phrase\". Let me digress a little further; originally a cliche was a printer's term, back in the days when letters were set one by one, for a ready-made block of type of frequently used phrases, usually in the newspaper business. So ... there you are ... um ... cliches were also known as stereotypes.\nNow, if you think of graphic design as a language with its own vocabulary, grammar, and so on, it too must have its cliches. Obvious examples would be, um, the twin Greek masks of comedy and tragedy that symbolize the theater and, more popularly known, the heart as a symbol of love, especially on Valentine cards, and so on. Far from being a terrible fault - as it would be in literature - the visual cliche is essential in the world of graphic communication. This is certainly true when it comes to advertising and propaganda. The visual cliche can give immediate life to an idea and a clear meaning to what could be a mere abstraction.\n\nClick on the paragraph that best relates to the recording.","pte_task_type":"HIGHLIGHT_CORRECT_SUMMARY","task_type_key":"HIGHLIGHT_CORRECT_SUMMARY","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"d946ba06-8238-4dfa-9da3-12a10b0b7196","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"While cliches in writing reveal lazy thinking and are to be avoided at all costs, in the graphic arts they become essential, helping to get the message across quickly, clearly and with emotional force. This is especially true of advertising and propaganda where the impact must be immediate.","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"39c562b4-9c59-48f9-8e88-5e5345ad1aea","availability_flags_explicit":true},{"id":80,"pool":"EXAM","title":"DOC22 HIGHLIGHT_CORRECT_SUMMARY c6cd1529a6fbb693 | HCS","status":"APPROVED","deleted":false,"version":1,"public_id":"f76b6029-68e9-492b-a08c-6eabd2f05b62","tenant_id":null,"created_at":"2026-10-28T16:07:36.698546+00:00","is_current":true,"updated_at":"2026-10-28T16:07:36.7088+00:00","visibility":"SHARED","prompt_text":"All whales, dolphins, and porpoises are social animals, although the degree of sociability varies greatly from one species to another. Differences of behavior have not evolved by chance. Living in close proximity to other animals has certain costs and benefits, so we can expect the group size adopted by a species to be the most suitable for its environment and lifestyle. River dolphins, for example, have a fairly simple social system, forming small groups of just a few animals- rarely more than ten. On the other hand, many of the oceanic dolphins may roam the seas in groups of thousands. Also, there can be differences within species: for example, with sperm whales, females and juveniles form groups while adult males are solitary. Some of the reasons for living in groups include greater efficiency in searching for and catching food, benefits for mating, learning, defence, and sensory integration. Now, sensory integration is the means by which each animal contributes to the information gained by the group as a whole, and this plays an important part in defence and in the search for food. For example, if one animal discovers a shoal of fish or a hungry shark, it can immediately pass on this information to the others in the group so that all may benefit. A single animal or small group may remain unaware of the food or predator, and so miss a meal or suffer an attack.\n\nClick on the paragraph that best relates to the recording.","pte_task_type":"HIGHLIGHT_CORRECT_SUMMARY","task_type_key":"HIGHLIGHT_CORRECT_SUMMARY","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"bae25b55-077b-4117-9c0f-0e77eaaaa36a","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"Dolphins, whales and porpoises are all social animals, but some species are more sociable than others. This depends on the environment because a species adopts the lifestyle most suitable for this. Among dolphins, forming groups makes it easier for them to find food, reproduce and gain knowledge. They are safer, too, because dolphins can communicate danger when there are threats around.","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"bba6474c-763d-4249-97f5-b14accbaacc0","availability_flags_explicit":true},{"id":81,"pool":"EXAM","title":"DOC22 HIGHLIGHT_CORRECT_SUMMARY f84c4c1faa8e32d2 | Proust's Novel","status":"APPROVED","deleted":false,"version":1,"public_id":"45229951-8e59-4417-bb96-640d20d1a1dd","tenant_id":null,"created_at":"2026-10-28T16:07:37.894502+00:00","is_current":true,"updated_at":"2026-10-28T16:07:37.904804+00:00","visibility":"SHARED","prompt_text":"In his great novel Remembrance of Things Past or In Search of Lost Time, Marcel Proust explored what are called \"involuntary memories\" - those that come to us quite suddenly without conscious effort, usually triggered by one of the senses. The fact that his book has two titles in English might suggest there is some doubt as to how our minds go about remembering things. In perhaps the most well-known such episode in the novel, the character Marcel is reminded of his childhood by the aroma produced when dunking a cake in a cup of tea. This is not far away from the belief that as we get older we can remember quite clearly incidents from years ago, but find it hard to remember what we did last week. Proust's insight into memory is certainly true of one way the mind works. But why and how do we remember what we do?\nExperts believe that we store memories in three ways. First, there is the sensory stage which is to do with perception and lasts only a fraction of a second, taking in sight, sound, touch, and so on. These first perceptions and sensations are then stored in the short-term memory, which is the second stage. Finally, important information or information that has been reinforced by, for example, repetition, is then filtered into the long-term memory. Naturally, we tend to more easily absorb material on things we already know something about, as this has more meaning for us and can create a web of connections with related material that is already stored in the long-term memory.\n\nClick on the paragraph that best relates to the recording.","pte_task_type":"HIGHLIGHT_CORRECT_SUMMARY","task_type_key":"HIGHLIGHT_CORRECT_SUMMARY","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"3b9f5acc-4fdc-446e-a66d-4e57cc54b95c","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"What we experience is processed by the brain into memories in three stages. First, there is the sensory input, which is momentary. This is then stored in the short-term memory. If this experience is important or meaningful to us, we will reinforce the memory, possibly by repetition, and it will then be stored in the long-term memory.","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"e4c1b308-2503-41e2-8c16-747ef6876828","availability_flags_explicit":true},{"id":82,"pool":"EXAM","title":"DOC22 MC_LISTENING_SINGLE ff1cf85b43365539 | Pop Music","status":"APPROVED","deleted":false,"version":1,"public_id":"f3b6d95d-905a-4446-a164-a615f22cb742","tenant_id":null,"created_at":"2026-10-28T16:07:38.900766+00:00","is_current":true,"updated_at":"2026-10-28T16:07:38.913456+00:00","visibility":"SHARED","prompt_text":"It is not often I get the chance to talk about the psychology of pop music, or rather the lyrics and the effect they have on young people. I must say at the outset that I'm not at all sure about the findings of a recent survey I've been studying, conducted over a period of 30 years. In short, it claims that late adolescents and college students are more narcissistic than ever before. This might well be true, and it might also be true that pop lyrics are becoming more self-absorbed, negative and violent. But this reflect the psychology of the writers and performers more than their listeners. Also, as the writers of the study are alarmed to discover, this radical increase in narcissism comes with higher levels of and depression which, if you think a bout it for a second, is hardly surprising. Furthermore, they have detected a link with heightened anger and problems maintaining relationships. Now, a couple of points: first, adolescents are pretty much self-absorbed anyway, but it's rarely pathological; also, you can_read almost anything you want into song lyrics from any era. Again, people nowadays find it easier to express themselves emotionally than thetr counterparts did 30 years ago. Last, the survey suggests a complete . personality change over the covered, yet I doubt that personality traits can change so much from one generation to another or, for that matter, from one culture to another.\n\nWhat is the speaker's attitude to the report on narcissism?","pte_task_type":"MC_LISTENING_SINGLE","task_type_key":"MC_LISTENING_SINGLE","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"3142c07a-e1d4-47cc-ac1c-18505b2e75fa","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"He is skeptical of it.","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"92a03bf3-6a22-442b-a833-4da69922b935","availability_flags_explicit":true},{"id":83,"pool":"EXAM","title":"DOC22 MC_LISTENING_SINGLE 32f123d9befa43bd | MCS-L","status":"APPROVED","deleted":false,"version":1,"public_id":"bec512e2-9b0a-4510-851e-06d357ce69b5","tenant_id":null,"created_at":"2026-10-28T16:07:40.063231+00:00","is_current":true,"updated_at":"2026-10-28T16:07:40.073169+00:00","visibility":"SHARED","prompt_text":"How would you define \"reasonable\" as it is used in law? For example, you are allowed to use \"reasonable force\" when defending yourself. It seems to depend on how serious the situation was, whether it was possible to resolve it by peaceful means, whether you were ready to try those means and, finally, the relative strengths of those involved. Now, most men know, and they've probably grasped this from their earliest years in the school playground, that, when it comes to blows, fights don't stop until one of you is in no shape to do any damage to the other. The criteria mentioned seem a bit fuzzy to me. How can you convince a jury you were ready to try and talk your way out of it when the other person would have none of it and, besides, he was quick to land the first punch? Also you can strike the first blow and still plead self-defence.\nOf course, you again have the problem of convincing people that the threat was so great that you had no alternative, apart from getting beaten up yourself. Reacting calmly and rationally to a perceived threat is not easy to do.\n\nWhich of the following is true according to the speaker?","pte_task_type":"MC_LISTENING_SINGLE","task_type_key":"MC_LISTENING_SINGLE","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"becd73c7-4323-4276-8e65-0c049b8b75db","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"Your use of force may be judged on how strong you are compared to the other person.","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"90ba262e-3536-4226-a0e5-36483a102e27","availability_flags_explicit":true},{"id":84,"pool":"EXAM","title":"DOC22 MC_LISTENING_SINGLE ae9b114b249c3ad3 | MCS-L","status":"APPROVED","deleted":false,"version":1,"public_id":"509e9478-70ba-48da-a2f1-1e343f8b503b","tenant_id":null,"created_at":"2026-10-28T16:07:41.184157+00:00","is_current":true,"updated_at":"2026-10-28T16:07:41.19558+00:00","visibility":"SHARED","prompt_text":"Randall Jarrell, the great American critic and poet, once defined the novel as, \"an extended piece of prose fiction with something wrong with it\". Now, nothing is perfect and you don't have to look very hard to find something wrong- or perhaps just something you don't like - about any work of fiction you care to name. Where, we might ask, does the editor come into this? And is it beneficial to an author to have an editor who is also a novelist? You would think that being a writer themselves, familiar with the process of writing a novel and its demands, they would be able to get inside the head of the author, and be sympathetic and understanding of what needs to be done. This is not an unreasonable assumption to make. However, is it not possible that there is an opposite side to this? Editors might, from their experience as writers, possibly unconsciously, try to make over the submitted novel as they themselves would have written it. The ideal, one supposes, is for the editor to see the book through the author's eyes, but if they apply their own creative talent to the job they might end up seeing it too much through their own eyes and, in this way, take no account of the author's original intentions.\n\nIn the speaker's opinion, which of the following is true of editors who are also novelists?","pte_task_type":"MC_LISTENING_SINGLE","task_type_key":"MC_LISTENING_SINGLE","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"23fe8e19-4fef-4fb0-b7a7-18722d5f8d73","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"They may try to re-shape the novelist's work in their own way.","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"90396adb-629f-4137-b836-6a0c4bf8b903","availability_flags_explicit":true},{"id":85,"pool":"EXAM","title":"DOC22 SELECT_MISSING_WORD c86186bb0a986d37 | Paper Money","status":"APPROVED","deleted":false,"version":1,"public_id":"4dab4bab-da2f-48f6-9619-e979c46da065","tenant_id":null,"created_at":"2026-10-28T16:07:42.443719+00:00","is_current":true,"updated_at":"2026-10-28T16:07:42.455517+00:00","visibility":"SHARED","prompt_text":"The Chinese were, as far as we know, the inventors of paper money and because it was so easy to move compared with coins, it was named \"flying money\". They were also the first to experience an economic problem which has become all too familiar: by the 12th century, there was money in circulation to cause serious inflation. In Europe, it wasn't until about 1400 that bankers in Spain and Italy began to honor \"bills of exchange\", which were a kind of private paper money not in general use. They were documents used by those involved in a business transaction in which payment was made through a third party to avoid the cost of foreign exchange. However, it is the Swedes who are generally credited with producing the first proper European bank [BEEP]\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.","pte_task_type":"SELECT_MISSING_WORD","task_type_key":"SELECT_MISSING_WORD","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"6786fc18-9b6f-47eb-b712-3ebde48390ac","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"notes","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"adc80548-e07f-466e-bbb1-b51863f1165a","availability_flags_explicit":true},{"id":86,"pool":"EXAM","title":"DOC22 SELECT_MISSING_WORD 558120624f93d194 | SMW","status":"APPROVED","deleted":false,"version":1,"public_id":"394b0a55-dc75-4268-9d5d-513e3cb060cd","tenant_id":null,"created_at":"2026-10-28T16:07:43.414778+00:00","is_current":true,"updated_at":"2026-10-28T16:07:43.427608+00:00","visibility":"SHARED","prompt_text":"So, just a few weeks ago excavators of a remote archeological site in southeastem Asia reported an exciting find under the ground, They found evidence of a writing system which dates back thousands of years. Three blocks of flat rock with odd symbols which look like ancient forms of writing were discovered. Well,this find could reveal much about an advanced, independent urban culture which historians believe may have lived in that area. However,many scholars are sceptical about the authenticity of the blocks,which they suspect - - - .\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.","pte_task_type":"SELECT_MISSING_WORD","task_type_key":"SELECT_MISSING_WORD","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"5770dd4f-9b4e-4d0c-bfd1-44ffa4d92ca0","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"could very possibly be fake","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"689366ad-0b48-46ab-a9a7-459669d3ced5","availability_flags_explicit":true},{"id":87,"pool":"EXAM","title":"DOC22 HIGHLIGHT_INCORRECT_WORDS 66524fe3b4b9a502 | [MOCK] Happy New Year","status":"APPROVED","deleted":false,"version":1,"public_id":"ad715e85-4204-47f8-bca6-06285c6a27d2","tenant_id":null,"created_at":"2026-10-28T16:07:44.514193+00:00","is_current":true,"updated_at":"2026-10-28T16:07:44.524912+00:00","visibility":"SHARED","prompt_text":"For many people, the start of a new year is a time to look forward on the past twelve months and make plans for the future. Some people celebrate with fireworks and large parties, while others prefer a noisy evening at home with family. A popular tradition is to make a resolution, such as exercising more or saving money. Unfortunately, studies show that most resolutions are remembered within a few weeks, often because the goals are too modest or too vague.","pte_task_type":"HIGHLIGHT_INCORRECT_WORDS","task_type_key":"HIGHLIGHT_INCORRECT_WORDS","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"7af0664c-66a0-461f-abf0-609715175fa2","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"[14,38,66,77]","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":"For many people, the start of a new year is a time to look back on the past twelve months and make plans for the future. Some people celebrate with fireworks and large parties, while others prefer a quiet evening at home with family. A popular tradition is to make a resolution, such as exercising more or saving money. Unfortunately, studies show that most resolutions are abandoned within a few weeks, often because the goals are too ambitious or too vague.","available_for_practice":false,"revision_group_public_id":"f74c497b-7ca8-44e8-a768-895c54cb8b02","availability_flags_explicit":true},{"id":88,"pool":"EXAM","title":"DOC22 HIGHLIGHT_INCORRECT_WORDS f554edb9ece898f8 | [MOCK] Woodpecker","status":"APPROVED","deleted":false,"version":1,"public_id":"89441970-ed16-4de8-b333-4683e4ba3ff4","tenant_id":null,"created_at":"2026-10-28T16:07:46.420481+00:00","is_current":true,"updated_at":"2026-10-28T16:07:46.433359+00:00","visibility":"SHARED","prompt_text":"Woodpeckers are well known for the loud drumming sound they make by striking their beaks against tree trunks. Scientists once believed that this behaviour was used only to find water, but we now know that drumming is also a form of silence. Each species has its own rhythm, which allows birds to ignore members of their own kind. Remarkably, the woodpecker's skull contains special bones and muscles that act like a hammer, protecting its brain from injury.","pte_task_type":"HIGHLIGHT_INCORRECT_WORDS","task_type_key":"HIGHLIGHT_INCORRECT_WORDS","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"a04d5cab-8669-4e4b-a662-43f522828bf7","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"[29,41,52,71]","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":"Woodpeckers are well known for the loud drumming sound they make by striking their beaks against tree trunks. Scientists once believed that this behaviour was used only to find food, but we now know that drumming is also a form of communication. Each species has its own rhythm, which allows birds to recognise members of their own kind. Remarkably, the woodpecker's skull contains special bones and muscles that act like a cushion, protecting its brain from injury.","available_for_practice":false,"revision_group_public_id":"d21b6c6c-7117-4d6f-9ba0-77d7c05c259e","availability_flags_explicit":true},{"id":89,"pool":"EXAM","title":"DOC22 HIGHLIGHT_INCORRECT_WORDS 4739d06f1965f619 | [MOCK] El Niño","status":"APPROVED","deleted":false,"version":1,"public_id":"b3cb9e46-f1ba-49f0-912a-24e119547e95","tenant_id":null,"created_at":"2026-10-28T16:07:47.529415+00:00","is_current":true,"updated_at":"2026-10-28T16:07:47.539834+00:00","visibility":"SHARED","prompt_text":"El Niño is a climate pattern that occurs when surface waters in the central Pacific Ocean become unusually cold. The event happens every two to seven years and can last for several days. Its effects are felt around the world: some regions experience heavy rain and flooding, while others suffer from severe floods. Because El Niño has such a strong influence on fashion, governments now use computer models to predict when the next event is likely to arrive.","pte_task_type":"HIGHLIGHT_INCORRECT_WORDS","task_type_key":"HIGHLIGHT_INCORRECT_WORDS","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"660f1852-f42a-41c0-87be-dedb81143788","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"[18,32,52,62]","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":"El Niño is a climate pattern that occurs when surface waters in the central Pacific Ocean become unusually warm. The event happens every two to seven years and can last for several months. Its effects are felt around the world: some regions experience heavy rain and flooding, while others suffer from severe drought. Because El Niño has such a strong influence on agriculture, governments now use computer models to predict when the next event is likely to arrive.","available_for_practice":false,"revision_group_public_id":"bddfc393-e564-4214-8c71-c0ff9d940c71","availability_flags_explicit":true},{"id":90,"pool":"EXAM","title":"DOC22 WRITE_FROM_DICTATION d86682422ffd6fda | WFD","status":"APPROVED","deleted":false,"version":1,"public_id":"867f18cf-d2d4-4cc7-81c4-9d08304812ef","tenant_id":null,"created_at":"2026-10-28T16:07:48.923252+00:00","is_current":true,"updated_at":"2026-10-28T16:07:48.934757+00:00","visibility":"SHARED","prompt_text":null,"pte_task_type":"WRITE_FROM_DICTATION","task_type_key":"WRITE_FROM_DICTATION","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"42ef9597-c434-4aa0-a092-0b63f1a5f876","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"The artists and conservative politicians follow their own rules in politics.","supersedes_public_id":n