y.","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"cde57552-8721-4e27-9109-0b628d65e306","availability_flags_explicit":true},{"id":93,"pool":"EXAM","title":"DOC22 WRITE_FROM_DICTATION 776ad3be5268468b | WFD","status":"APPROVED","deleted":false,"version":1,"public_id":"9cc1767a-c29d-4074-a611-52b74a262a10","tenant_id":null,"created_at":"2026-10-28T16:07:51.836331+00:00","is_current":true,"updated_at":"2026-10-28T16:07:51.845375+00:00","visibility":"SHARED","prompt_text":null,"pte_task_type":"WRITE_FROM_DICTATION","task_type_key":"WRITE_FROM_DICTATION","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":"65e100a9-aadc-4b7a-9793-a8954df7d0f3","image_prompt_ref":null,"rejection_reason":null,"task_type_section":"LISTENING","available_for_exam":true,"correct_answer_text":"You will acquire many skills during your academic studies.","supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":null,"available_for_practice":false,"revision_group_public_id":"474f4097-e11e-4489-859b-eb4347a4349c","availability_flags_explicit":true},{"id":94,"pool":"EXAM","title":"DOC22 DESCRIBE_IMAGE b52d62b0436aa8fa | [MOCK] Height of Tree","status":"APPROVED","deleted":false,"version":1,"public_id":"fd60b09d-5517-49d0-946e-1634f1891380","tenant_id":null,"created_at":"2026-10-28T16:19:02.472749+00:00","is_current":true,"updated_at":"2026-10-28T16:19:02.51065+00:00","visibility":"SHARED","prompt_text":null,"pte_task_type":"DESCRIBE_IMAGE","task_type_key":"DESCRIBE_IMAGE","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":null,"image_prompt_ref":"1388ce12-a986-4ee2-97a0-4659c19c467e","rejection_reason":null,"task_type_section":"SPEAKING","available_for_exam":true,"correct_answer_text":null,"supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":"The following graph gives information about heights of trees.\nThe items include hemlock, cedar, spruce, Douglas fir.\nAccording to this graph, in Hemlock, the height is around 130 feet, and that of Cedar is higher, which is around 200 feet.\nYou can see from this graph that the greatest value of height is in Douglas Fir, around 280 feet.\nTo sum up, the graph tells about different heights of trees.","available_for_practice":false,"revision_group_public_id":"3d1f5aa3-a3da-4dbb-94cc-f423a20416a4","availability_flags_explicit":true},{"id":95,"pool":"EXAM","title":"DOC22 DESCRIBE_IMAGE bacd6f8fd1fdc950 | [MOCK] Electricity Generation","status":"APPROVED","deleted":false,"version":1,"public_id":"bd0bd365-4f22-4a6e-99a9-44940ae6de3a","tenant_id":null,"created_at":"2026-10-28T16:19:03.598284+00:00","is_current":true,"updated_at":"2026-10-28T16:19:03.6475+00:00","visibility":"SHARED","prompt_text":null,"pte_task_type":"DESCRIBE_IMAGE","task_type_key":"DESCRIBE_IMAGE","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":null,"image_prompt_ref":"a47e2d64-e6a7-45e8-aa9e-52d78e7456b7","rejection_reason":null,"task_type_section":"SPEAKING","available_for_exam":true,"correct_answer_text":null,"supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":"The following graph gives information about electricity generation in China by type from 1994 to 2004.\nFor the conventional thermal, it has increased from 600 in 1994 to 1500 in 2004 gradually.\nWhen we look at the hydroelectric, it remained relatively stable at around 100 throughout the period. For the total generation, it has increased dramatically from 900 to 2000 from 1994 to 2004.\nTo sum up, conventional thermal still occupies the largest part of electricity generation in China.","available_for_practice":false,"revision_group_public_id":"301358bb-442a-4df5-9a85-c19ef2a13046","availability_flags_explicit":true},{"id":96,"pool":"EXAM","title":"DOC22 PERSONAL_INTRODUCTION 8d96be61e9b3b468 | [MOCK] Study Abroad Plans","status":"APPROVED","deleted":false,"version":1,"public_id":"79717c31-c9ba-4afd-a4d2-5d0afd71882b","tenant_id":null,"created_at":"2026-10-28T16:48:18.318692+00:00","is_current":true,"updated_at":"2026-10-28T16:48:18.333543+00:00","visibility":"SHARED","prompt_text":"Please introduce yourself. For example, you could talk about one or more of the following:\n\n• Your interests\n• Your plans for future study\n• Why you want to study abroad\n• Why you need to learn English\n• Why you chose this test","pte_task_type":"PERSONAL_INTRODUCTION","task_type_key":"PERSONAL_INTRODUCTION","ever_published":true,"max_word_count":null,"min_word_count":null,"revision_number":1,"audio_prompt_ref":null,"image_prompt_ref":null,"rejection_reason":null,"task_type_section":"SPEAKING","available_for_exam":true,"correct_answer_text":null,"supersedes_public_id":null,"author_user_public_id":"cc916708-5818-45ad-a707-c34482f5fd97","reference_answer_text":"Hello, my name is Minh and I am twenty-two years old. I have just finished my bachelor's degree in computer science in Ho Chi Minh City. I am very interested in artificial intelligence, so I plan to do a master's degree in Australia next year. I need a good English score because all of the courses are taught in English. I chose this test because it is fast, fair and accepted by my university.","available_for_practice":false,"revision_group_public_id":"202380ae-14a7-4185-a455-32e9d2e3b993","availability_flags_explicit":true}]$seed_e99a914190f0$::jsonb);

