2,"question_id":71,"correct_gap_index":4},{"text":"aspect","correct":true,"public_id":"da4703ac-b638-477f-8201-c385ecd4cff3","blank_index":null,"order_index":3,"question_id":71,"correct_gap_index":2},{"text":"limit","correct":true,"public_id":"162649a6-ffd2-4bc3-b87a-7d0dec7d54b4","blank_index":null,"order_index":4,"question_id":71,"correct_gap_index":3},{"text":"experiment","correct":false,"public_id":"7dff8050-5de8-41ff-9445-482e1466dfe2","blank_index":null,"order_index":5,"question_id":71,"correct_gap_index":null},{"text":"recruits","correct":true,"public_id":"5e9d0dfa-f106-4ac0-b7ab-823d045e268f","blank_index":null,"order_index":6,"question_id":71,"correct_gap_index":0},{"text":"posture","correct":false,"public_id":"6e89067c-b7e7-4920-8983-96777d6ad2fe","blank_index":null,"order_index":7,"question_id":71,"correct_gap_index":null},{"text":"The appreciation of natural beauty","correct":false,"public_id":"0fd894af-4662-45b8-9209-d641b8a8e8cf","blank_index":null,"order_index":0,"question_id":73,"correct_gap_index":null},{"text":"The Romantic Movement","correct":true,"public_id":"93256265-79ce-435a-8ea5-979c49fc8a91","blank_index":null,"order_index":1,"question_id":73,"correct_gap_index":null},{"text":"A person's political affiliations","correct":false,"public_id":"7b714903-8b41-4ade-a28f-020582eb1890","blank_index":null,"order_index":2,"question_id":73,"correct_gap_index":null},{"text":"Italian classical painting","correct":true,"public_id":"95939709-fd1b-4620-80b2-028e00a9aaa1","blank_index":null,"order_index":3,"question_id":73,"correct_gap_index":null},{"text":"Gardens from classical Greece and Rome","correct":false,"public_id":"2ed20863-017a-4e27-afe4-e776ff2b6263","blank_index":null,"order_index":4,"question_id":73,"correct_gap_index":null},{"text":"how attractive the building is to look at","correct":true,"public_id":"47fd205c-f26a-4f6c-875f-2a00543cb1c2","blank_index":null,"order_index":0,"question_id":74,"correct_gap_index":null},{"text":"how original the design of the building is","correct":false,"public_id":"0d1c240f-22b9-4881-82e9-3f10627c2063","blank_index":null,"order_index":1,"question_id":74,"correct_gap_index":null},{"text":"how well the building fits in with surrounding buildings","correct":false,"public_id":"122850a2-112a-4ac5-bd16-76758d2989bb","blank_index":null,"order_index":2,"question_id":74,"correct_gap_index":null},{"text":"how long the building is likely to last","correct":true,"public_id":"af640d74-af14-4573-8db0-641b1a0d6dd7","blank_index":null,"order_index":3,"question_id":74,"correct_gap_index":null},{"text":"how well the building suits its purpose","correct":false,"public_id":"88256a63-579c-49d3-a7ca-9072fdf564ea","blank_index":null,"order_index":4,"question_id":74,"correct_gap_index":null},{"text":"Men form societies to better cope with the dangers in life.","correct":true,"public_id":"9f5b93d8-3ef4-4e9f-b64e-32820ec2e45b","blank_index":null,"order_index":0,"question_id":75,"correct_gap_index":null},{"text":"Society has a corrupting influence on people.","correct":false,"public_id":"5644da92-e971-4131-acc4-69f5516c3250","blank_index":null,"order_index":1,"question_id":75,"correct_gap_index":null},{"text":"People were far happier in a \"state of nature\" before civilization.","correct":false,"public_id":"eff0e52d-3053-4ac8-ada1-77fe7f87be86","blank_index":null,"order_index":2,"question_id":75,"correct_gap_index":null},{"text":"By forming societies, law and morality come into force.","correct":true,"public_id":"dba7b36c-dc58-4134-a374-52eba06af846","blank_index":null,"order_index":3,"question_id":75,"correct_gap_index":null},{"text":"Children's emotions should be educated before their intellect.","correct":false,"public_id":"a86914d2-feb1-4d28-afbb-2d09edc14ed1","blank_index":null,"order_index":4,"question_id":75,"correct_gap_index":null},{"text":"Cliches are the enemy of literature and art. They are words, phrases and images that have become stale through overuse and therefore have nothing new to say to us. They are an enemy to clear and original thinking, although they are sometimes useful in advertising to get a simple message across.","correct":false,"public_id":"6d4162e8-87ac-4fb1-b344-664be8e8d447","blank_index":null,"order_index":0,"question_id":79,"correct_gap_index":null},{"text":"While cliches in writing reveal lazy thinking and are to be avoided at all costs, in the graphic arts they become essential, helping to get the message across quickly, clearly and with emotional force. This is especially true of advertising and propaganda where the impact must be immediate.","correct":true,"public_id":"fee09614-18fc-42e9-9332-cd3604da0b50","blank_index":null,"order_index":1,"question_id":79,"correct_gap_index":null},{"text":"Cliches are worn out, overused and over-familiar phrases, and the etymology of the word helps to explain this. Originally, a cliche or stereotype was a printer's term for a pre-set block of type with phrases used frequently in the newspapers. The word has since adopted a negative meaning and careful writers avoid them where they can.","correct":false,"public_id":"7d1186df-f5e3-4e7a-b70a-1829b1082721","blank_index":null,"order_index":2,"question_id":79,"correct_gap_index":null},{"text":"Cliches, whether in language or graphic design, are entirely worthless and should be eliminated in all fields. In literature, they destroy original thinking, and in graphic arts, they only create confusion instead of conveying clear messages.","correct":false,"public_id":"ff7129c7-3ade-4d67-97b3-8d0a287a4111","blank_index":null,"order_index":3,"question_id":79,"correct_gap_index":null},{"text":"Dolphins, whales and porpoises are all social animals, but some species are more sociable than others. This depends on the environment because a species adopts the lifestyle most suitable for this. Among dolphins, forming groups makes it easier for them to find food, reproduce and gain knowledge. They are safer, too, because dolphins can communicate danger when there are threats around.","correct":true,"public_id":"20f49719-94af-440a-b998-ff6312bdb060","blank_index":null,"order_index":0,"question_id":80,"correct_gap_index":null},{"text":"The speaker explains that whales, dolphins, and porpoises have evolved differently and face different threats. River dolphin numbers are declining, while ocean dolphins are doing well in spite of the threats they face. The reason for this is that ocean dolphins are better adapted for finding food and avoiding predators.","correct":false,"public_id":"7b700751-5552-4ab6-8867-5f106fdf7889","blank_index":null,"order_index":1,"question_id":80,"correct_gap_index":null},{"text":"Dolphins have adopted group living as a response to living in close contact with other animals in the ocean, some of which kill dolphins for food. Living in social groups makes it easier to hunt for food and, in a dangerous environment, it makes sense in terms of safety to move about in large numbers.","correct":false,"public_id":"b5c766b2-7cca-4fd3-8afe-b2ab2bfca540","blank_index":null,"order_index":2,"question_id":80,"correct_gap_index":null},{"text":"The speaker talks about the use of memory in Proust's novel In Search of Lost Time and how memories are usually brought about by the taste or smell of something, in this case, a biscuit dipped in tea. So, it is the senses that provoke memories that can take us back to our childhood.","correct":false,"public_id":"df3a4448-e351-475c-93ad-01b75921b297","blank_index":null,"order_index":0,"question_id":81,"correct_gap_index":null},{"text":"Using the writer Proust as an example, the speaker tells us how long-term memory works before going on to talk about short-term memory. Distant memories are usually involuntary and are brought to mind by something that stimulates one of the senses. Short-term memory also requires sensory input, but it lasts only a fraction of a second.","correct":false,"public_id":"c9f4f7cf-45fc-4d04-9a67-b6e574005bd3","blank_index":null,"order_index":1,"question_id":81,"correct_gap_index":null},{"text":"What we experience is processed by the brain into memories in three stages. First, there is the sensory input, which is momentary. This is then stored in the short-term memory. If this experience is important or meaningful to us, we will reinforce the memory, possibly by repetition, and it will then be stored in the long-term memory.","correct":true,"public_id":"23f47962-c60b-4623-b50b-85a5275c2fd5","blank_index":null,"order_index":2,"question_id":81,"correct_gap_index":null},{"text":"He is amused by it.","correct":false,"public_id":"029acada-4adb-4f9d-aa36-b402141d6186","blank_index":null,"order_index":0,"question_id":82,"correct_gap_index":null},{"text":"He doesn't believe any of it is true.","correct":false,"public_id":"0fdd877d-0a53-43d4-85f2-4d91c334acfb","blank_index":null,"order_index":1,"question_id":82,"correct_gap_index":null},{"text":"He is angered by it.","correct":false,"public_id":"b70dec2c-f21b-464d-ad50-ee1be9d45488","blank_index":null,"order_index":2,"question_id":82,"correct_gap_index":null},{"text":"He is skeptical of it.","correct":true,"public_id":"ad0f495d-0a6f-4f64-bd1e-2e97776779a7","blank_index":null,"order_index":3,"question_id":82,"correct_gap_index":null},{"text":"The concept of reasonable force is very clearly defined.","correct":false,"public_id":"aa158350-f67b-4fcf-86fc-d1ed43db2ccd","blank_index":null,"order_index":0,"question_id":83,"correct_gap_index":null},{"text":"Your use of force may be judged on how strong you are compared to the other person.","correct":true,"public_id":"caa150cd-1d67-419f-af3c-88e3b860e406","blank_index":null,"order_index":1,"question_id":83,"correct_gap_index":null},{"text":"If you hit someone first, you cannot then claim self-defence.","correct":false,"public_id":"b50a42a4-895d-4d43-b6c9-7e1ceaf04afb","blank_index":null,"order_index":2,"question_id":83,"correct_gap_index":null},{"text":"Courts do not expect ordinary people to react rationally.","correct":false,"public_id":"568409a8-9583-4005-86b2-d71686f5d466","blank_index":null,"order_index":3,"question_id":83,"correct_gap_index":null},{"text":"They are always able to see the novel from the author's point of view.","correct":false,"public_id":"a6b1b5d9-b96f-4ee0-a0f7-12045320d419","blank_index":null,"order_index":0,"question_id":84,"correct_gap_index":null},{"text":"They are sympathetic to the difficult lives authors lead.","correct":false,"public_id":"34c44d38-a133-45ee-8310-aa9d726c0bbd","blank_index":null,"order_index":1,"question_id":84,"correct_gap_index":null},{"text":"They may try to re-shape the novelist's work in their own way.","correct":true,"public_id":"81222263-dd73-4556-be8a-1cd6632b3bb0","blank_index":null,"order_index":2,"question_id":84,"correct_gap_index":null},{"text":"They find it difficult to see the author's real intentions.","correct":false,"public_id":"5682e735-e01b-4363-ab00-7b1b1a085c14","blank_index":null,"order_index":3,"question_id":84,"correct_gap_index":null},{"text":"notes","correct":true,"public_id":"d0e10e64-b4a8-46ee-a6f9-0bc66dda2588","blank_index":null,"order_index":0,"question_id":85,"correct_gap_index":null},{"text":"accounts","correct":false,"public_id":"f9c6fa7c-24c5-4617-b8aa-963729a05cb4","blank_index":null,"order_index":1,"question_id":85,"correct_gap_index":null},{"text":"drafts","correct":false,"public_id":"8312abef-4bd0-4496-aff5-eaa465a6eba3","blank_index":null,"order_index":2,"question_id":85,"correct_gap_index":null},{"text":"paper","correct":false,"public_id":"008685fa-0de7-4062-9384-10da7c4d729e","blank_index":null,"order_index":3,"question_id":85,"correct_gap_index":null},{"text":"charges","correct":false,"public_id":"24aa86ff-77cd-4c55-9f5e-6aba18880619","blank_index":null,"order_index":4,"question_id":85,"correct_gap_index":null},{"text":"are much older than expected","correct":false,"public_id":"ec06f18e-23c5-4f8e-99f0-ff47e8aa306b","blank_index":null,"order_index":0,"question_id":86,"correct_gap_index":null},{"text":"could very possibly be fake","correct":true,"public_id":"418aa2f9-cc5c-4103-93e7-177cd945f4b1","blank_index":null,"order_index":1,"question_id":86,"correct_gap_index":null},{"text":"belonged to that culture","correct":false,"public_id":"63479432-c271-455d-ab2d-ee4d9b752883","blank_index":null,"order_index":2,"question_id":86,"correct_gap_index":null}]$seed_b81112fedb60$::jsonb);

DELETE FROM question_options WHERE question_id IN (SELECT p.id FROM questions p JOIN seed_questions s USING (public_id));

INSERT INTO question_options ("text", "correct", "public_id", "blank_index", "order_index", "question_id", "correct_gap_index")
SELECT s."text", s."correct", s."public_id", s."blank_index", s."order_index", target.id, s."correct_gap_index"
FROM seed_question_options s JOIN seed_questions source ON source.id=s.question_id
JOIN questions target ON target.public_id=source.public_id;

