DELETE FROM exam_definition_items WHERE exam_definition_id IN (SELECT p.id FROM exam_definitions p JOIN seed_exam_definitions s USING (public_id));

INSERT INTO exam_definition_items ("section", "sequence", "max_count", "min_count", "task_type", "prep_seconds", "task_type_key", "overall_weight", "reading_weight", "scoring_method", "writing_weight", "speaking_weight", "listening_weight", "response_seconds", "exam_definition_id", "runtime_screen_key", "runtime_profile_key", "runtime_behavior_key", "runtime_renderer_key", "runtime_scoring_mode", "runtime_profile_status", "runtime_min_app_version", "runtime_profile_version", "runtime_contract_version", "runtime_scoring_profile_key", "runtime_answer_schema_version", "runtime_authoring_contract_key", "runtime_scoring_profile_version", "runtime_authoring_contract_version", "runtime_required_client_capabilities")
SELECT s."section", s."sequence", s."max_count", s."min_count", s."task_type", s."prep_seconds", s."task_type_key", s."overall_weight", s."reading_weight", s."scoring_method", s."writing_weight", s."speaking_weight", s."listening_weight", s."response_seconds", target.id, s."runtime_screen_key", s."runtime_profile_key", s."runtime_behavior_key", s."runtime_renderer_key", s."runtime_scoring_mode", s."runtime_profile_status", s."runtime_min_app_version", s."runtime_profile_version", s."runtime_contract_version", s."runtime_scoring_profile_key", s."runtime_answer_schema_version", s."runtime_authoring_contract_key", s."runtime_scoring_profile_version", s."runtime_authoring_contract_version", s."runtime_required_client_capabilities"
FROM seed_exam_definition_items s JOIN seed_exam_definitions source ON source.id=s.exam_definition_id
JOIN exam_definitions target ON target.public_id=source.public_id;

DO $validate$
BEGIN
  IF EXISTS (SELECT 1 FROM seed_questions s LEFT JOIN question_types t USING (task_type_key)
             WHERE t.id IS NULL) THEN
    RAISE EXCEPTION 'Question task-type reference missing';
  END IF;
  IF EXISTS (SELECT 1 FROM seed_questions q LEFT JOIN media_objects m
             ON m.public_id=q.audio_prompt_ref WHERE q.audio_prompt_ref IS NOT NULL AND m.id IS NULL)
     OR EXISTS (SELECT 1 FROM seed_questions q LEFT JOIN media_objects m
             ON m.public_id=q.image_prompt_ref WHERE q.image_prompt_ref IS NOT NULL AND m.id IS NULL) THEN
    RAISE EXCEPTION 'Question media reference missing';
  END IF;
  IF (SELECT count(*) FROM exam_definitions WHERE status='ACTIVE') <> 1 THEN
    RAISE EXCEPTION 'Exactly one active template is required';
  END IF;
END $validate$;
COMMIT;
